let parsed;
try {
  parsed = JSON.parse($json.message?.content ?? '{}');
} catch (e) {
  return [{ json: { shouldPropose: false } }];
}

const rawProposals = Array.isArray(parsed.proposals) ? parsed.proposals : [];

const seen = new Set();
const results = [];
for (const p of rawProposals) {
  const kebabName = (p?.name ?? '')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/-+/g, '-')
    .slice(0, 64)
    .replace(/^-|-$/g, '');

  if (!kebabName || !p?.description || !p?.reason) continue;
  if (seen.has(kebabName)) continue;
  seen.add(kebabName);

  const gapType = ['capability', 'functionality', 'knowledge'].includes(p?.gap_type) ? p.gap_type : 'capability';

  results.push({ json: {
    shouldPropose: true,
    kind: p.kind === 'tool_idea' ? 'tool_idea' : 'instruction',
    gap_type: gapType,
    name: kebabName,
    description: p.description,
    reason: p.reason,
    instructions: p.instructions ?? '',
    tool_idea_details: p.tool_idea_details ?? '',
  } });
}

return results.length ? results : [{ json: { shouldPropose: false } }];

