let parsed;
try {
  parsed = JSON.parse($json.message?.content ?? '{}');
} catch (e) {
  return [{ json: { shouldPropose: false } }];
}
if (!parsed.shouldPropose || !parsed.proposedSystemPrompt?.trim() || !parsed.proposedReason?.trim()) {
  return [{ json: { shouldPropose: false } }];
}
return [{ json: {
  shouldPropose: true,
  proposedSystemPrompt: parsed.proposedSystemPrompt,
  proposedReason: parsed.proposedReason,
} }];

const candidates = $input.all().map(i => i.json).filter(c => c.shouldPropose);
if (candidates.length === 0) {
  return [{ json: { shouldPropose: false } }];
}

const existingSkills = $('Get All Skills').all().map(i => i.json).filter(s => s.name);
const existingSkillsText = existingSkills.length
  ? existingSkills.map(s => `- ${s.name} [${s.kind}, ${s.status}]: ${s.description}`).join('\n')
  : '(none)';
const candidatesText = candidates.map((c, i) => `${i + 1}. ${c.name}: ${c.description}`).join('\n');

let duplicateIndices = [];
try {
  const data = await this.helpers.httpRequest({
    method: 'POST',
    url: 'http://ollama:11434/api/chat',
    body: {
      model: 'qwen3:8b',
      stream: false,
      think: false,
      messages: [
        {
          role: 'system',
          content: "You are checking new skill proposals for duplicates against a list of existing skills (any status). Two are duplicates if they address the SAME underlying gap or need, even when worded completely differently (different names, phrasing, synonyms) - judge by substance, not matching words. For each numbered candidate below that duplicates an existing skill, return its number. A candidate that is genuinely new/distinct should not be returned.",
        },
        {
          role: 'user',
          content: `Existing skills:\n${existingSkillsText}\n\nNumbered candidate proposals:\n${candidatesText}`,
        },
      ],
      format: {
        type: 'object',
        properties: { duplicateNumbers: { type: 'array', items: { type: 'number' } } },
        required: ['duplicateNumbers'],
      },
    },
    json: true,
  });
  const parsed = JSON.parse(data.message?.content ?? '{}');
  duplicateIndices = Array.isArray(parsed.duplicateNumbers) ? parsed.duplicateNumbers.map((n) => n - 1) : [];
} catch (e) {
  // Fail open - a dedup-check hiccup must never silently swallow a
  // genuine proposal, same defensive spirit as onError:
  // continueRegularOutput elsewhere in this project.
  duplicateIndices = [];
}

const duplicateSet = new Set(duplicateIndices);
const survivors = candidates.filter((c, i) => !duplicateSet.has(i));

return survivors.length ? survivors.map((c) => ({ json: c })) : [{ json: { shouldPropose: false } }];

const results = [];
for (const item of $input.all()) {
  const messages = item.json.items || [];
  const hasUserTurn = messages.some((m) => m.peer_id === 'user');
  // A real chat turn always inserts a user+amy pair together (see Chat
  // workflow's message-insert node) - a session with no user-authored
  // message at all is a one-way notification (e.g. the coding-agent
  // pipeline's own "Finished: ..." chat notifications), not a real
  // conversation that could contain a correction sequence.
  if (messages.length < 2 || !hasUserTurn) continue;

  const transcript = messages
    .map((m) => (m.peer_id === 'user' ? 'User' : 'Amy') + ': ' + m.content)
    .join('\n');
  results.push({ json: { transcript } });
}
// Safety cap - real usage volume is low for this project, but bound the
// worst case rather than assuming it always will be.
return results.slice(0, 8);

parameters.jsonBody:
={{ JSON.stringify({
  model: "qwen3:8b",
  stream: false,
  think: false,
  messages: [
    { role: "system", content: "You are reviewing one full conversation transcript between a user and Amy (an AI assistant) to find a very specific pattern: did the user have to correct Amy's approach two or more separate times before something finally worked correctly? For example: the user asks for something, Amy tries an approach, the user says something like 'no not that, do X instead', Amy tries again, the user corrects again ('actually, check Y first'), and eventually the right approach emerges (the user confirms it, or simply moves on without correcting again). This is different from a single one-off tweak or a simple clarification - it must be a genuine multi-round correction chain (at least two distinct corrections) that reveals something worth writing down so Amy follows it correctly next time without being re-taught. If you find such a sequence, distinguish between what was SPECIFIC TO THIS ONE REQUEST (the particular values, names, or targets this exact user message happened to mention) and the GENERAL, REUSABLE PROCEDURE the correction actually reveals. Do not just record literally what happened as a one-off transcript of this exact instance - generalize it into a procedure that correctly handles a DIFFERENT future request of the same underlying kind, not just an exact repeat of this one. For example, if the user corrected Amy about moving specific widgets to specific positions, the real lesson is the general approach (check the actual current state before reporting or changing anything, work out what state the request actually implies, apply only that change, then verify and accurately report what was actually done) - not the specific instance (which two widgets, which exact positions). However, if the correction was about a genuinely reusable technical procedure - specific commands, tool names, exact configuration - keep those literal and specific, since that specificity is exactly what makes it useful; only generalize the parts that were incidental to this one conversation, never vague away real technical detail into generic advice like 'communicate clearly'. Never include the rejected attempts as steps. The name field must be ONLY a short, plain skill name (a few words, no prefix, no punctuation beyond spaces/hyphens) - never put 'Corrected procedure:' or any other label in the name field. Only the reason field must start with the exact literal text 'Corrected procedure:' followed by a one-sentence explanation. Never propose something a competent assistant should already know without correction, and never propose a fix for a one-off isolated mistake that is not a real repeatable procedure. If no such multi-round correction chain exists in this transcript, return found: false and leave the other fields as empty strings." },
    { role: "user", content: $json.transcript }
  ],
  options: { num_ctx: 16384 },
  format: {
    type: "object",
    properties: {
      found: { type: "boolean" },
      name: { type: "string" },
      description: { type: "string" },
      reason: { type: "string" },
      instructions: { type: "string" }
    },
    required: ["found", "name", "description", "reason", "instructions"]
  }
}) }}

