const results = [];
for (const item of $input.all()) {
  let parsed;
  try {
    parsed = JSON.parse(item.json.message?.content ?? '{}');
  } catch (e) {
    continue;
  }
  if (!parsed.found) continue;

  const kebabName = (parsed.name ?? '')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/-+/g, '-')
    .slice(0, 64)
    .replace(/^-|-$/g, '');

  if (!kebabName || !parsed.description || !parsed.instructions) continue;

  results.push({ json: {
    shouldPropose: true,
    kind: 'instruction',
    name: kebabName,
    description: parsed.description,
    reason: parsed.reason || 'Corrected procedure: extracted from an observed multi-step correction sequence.',
    instructions: parsed.instructions,
    tool_idea_details: '',
  } });
}

return results.length ? results : [{ json: { shouldPropose: false } }];
